//! Domain models mirroring the Go API's JSON contract
//! (`backend/internal/handlers`: `userResponse`, `loginResponse`,
//! `friendshipResponse`, `locationShareResponse`, `locationResponse`).

use crate::osm::{Route, SearchPlace};
use crate::update::UpdateStatus;
use serde::{Deserialize, Serialize};

/// Authenticated user as returned in the `user` field of login/register.
/// `password_hash`/`totp_secret`/`mfa_last_step` are write-only (never serialized).
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct User {
    pub id: i64,
    /// Public handle generated by the server (`calm-otter-42`). Empty when
    /// talking to an older server; clients display it but never compute it.
    #[serde(default)]
    pub username: String,
    pub email: String,
    pub full_name: String,
    pub role: String,
    pub is_active: bool,
    pub must_change_password: bool,
    #[serde(skip_serializing, default)]
    pub password_hash: Option<String>,
    #[serde(skip_serializing, default)]
    pub totp_secret: Option<String>,
    #[serde(default)]
    pub mfa_enabled: bool,
    /// Last consumed TOTP step (replay protection). Server-only.
    #[serde(skip_serializing, default)]
    pub mfa_last_step: u64,
    /// Failed login attempts (lockout). Server-only.
    #[serde(skip_serializing, default)]
    pub failed_login_attempts: u32,
    /// ISO-8601 lockout expiry (None = not locked). Server-only.
    #[serde(skip_serializing, default)]
    pub locked_until: Option<String>,
    /// Authentication model: `email` | `anonymous` | `oauth` | `passkey`.
    #[serde(default = "default_auth_method")]
    pub auth_method: String,
    /// Device public key (base64) for anonymous accounts; null otherwise.
    #[serde(default)]
    pub public_key: Option<String>,
    /// PBKDF2 hash of the anonymous recovery code; null otherwise.
    #[serde(default)]
    pub recovery_code_hash: Option<String>,
    /// IdP subject for OAuth accounts (future); null otherwise.
    #[serde(default)]
    pub identity_subject: Option<String>,
}

/// A user-initiated diagnostic report. Deliberately minimal: category and
/// message only, plus the public handle of a signed-in reporter. No IP,
/// location, device identifier or email is stored.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct DiagnosticReport {
    pub id: i64,
    #[serde(default)]
    pub user_id: Option<i64>,
    #[serde(default)]
    pub username: Option<String>,
    pub category: String,
    pub message: String,
    #[serde(default)]
    pub app_version: String,
    #[serde(default)]
    pub platform: String,
    #[serde(default = "default_report_status")]
    pub status: String,
    pub created_at: String,
}

fn default_report_status() -> String {
    "open".to_string()
}

/// Append-only admin accountability record (who changed what). Stores ids and
/// public handles only — never email addresses or location data.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct AdminAuditEntry {
    pub id: i64,
    pub actor_id: i64,
    pub actor_username: String,
    pub action: String,
    pub target: String,
    #[serde(default)]
    pub detail: Option<String>,
    pub created_at: String,
}

fn default_auth_method() -> String {
    "email".to_string()
}

/// Envelope of `POST /api/v1/auth/login` and `POST /api/v1/auth/register`.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct LoginResponse {
    #[serde(default)]
    pub access_token: String,
    #[serde(default)]
    pub csrf_token: Option<String>,
    pub user: User,
}

/// One active server-side session as shown by the account/session manager.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct SessionInfo {
    pub id: String,
    #[serde(default)]
    pub current: bool,
    #[serde(default)]
    pub auth_method: String,
    #[serde(default)]
    pub mfa_pending: bool,
    #[serde(default)]
    pub created_at: String,
    #[serde(default)]
    pub last_activity: String,
}

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct Friendship {
    pub id: i64,
    pub requester_id: i64,
    pub receiver_id: i64,
    pub requester_name: String,
    pub receiver_name: String,
    /// `pending` | `accepted` | `rejected`
    pub status: String,
    #[serde(default)]
    pub created_at: Option<String>,
    #[serde(default)]
    pub responded_at: Option<String>,
}

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct LocationShare {
    pub id: i64,
    pub friendship_id: i64,
    pub owner_id: i64,
    /// `to_friend` | `from_friend` | `mutual`
    pub direction: String,
    /// `exact` | `approximate` | `city_only`
    pub precision_level: String,
    pub is_active: bool,
    #[serde(default)]
    pub last_location_update_at: Option<String>,
    /// Optional ISO-8601 expiry; expired shares are treated as inactive.
    #[serde(default)]
    pub expires_at: Option<String>,
    /// Optional human label (e.g. "Trip to cabin").
    #[serde(default)]
    pub label: Option<String>,
}

/// A friend's location as visible to the caller, already rounded by the
/// server according to the active share's precision level.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct FriendLocation {
    pub user_id: i64,
    pub user_name: String,
    pub latitude: f64,
    pub longitude: f64,
    pub precision_level: String,
    pub updated_at: String,
    #[serde(default)]
    pub accuracy: Option<f64>,
}

/// A trip / scheduled / manual check-in (latest retained per user + history
/// list). Check-ins are explicit user actions, never auto-tracked.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct CheckIn {
    pub id: i64,
    pub user_id: i64,
    pub user_name: String,
    pub latitude: f64,
    pub longitude: f64,
    #[serde(default)]
    pub note: String,
    /// `manual` | `scheduled` | `trip`
    pub kind: String,
    pub created_at: String,
}

/// A panic/emergency alert: activates all shares and publishes the location.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct EmergencyAlert {
    pub id: i64,
    pub user_id: i64,
    pub user_name: String,
    pub latitude: f64,
    pub longitude: f64,
    pub created_at: String,
    #[serde(default)]
    pub resolved: bool,
}

/// Local user preferences persisted on-device (never synced).
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct Settings {
    /// Auto-refresh interval in seconds (0 = off).
    #[serde(default = "default_refresh_interval")]
    pub refresh_interval_secs: u64,
    /// true = metric (km/m), false = imperial (mi/ft).
    #[serde(default = "default_metric")]
    pub metric: bool,
    /// Default precision for new shares.
    #[serde(default = "default_precision")]
    pub default_precision: String,
    /// Profile visibility: "friends_only" (default) or "public".
    #[serde(default = "default_visibility")]
    pub profile_visibility: String,
    /// UI language code (ISO 639-1). Empty = auto-detect from OS locale.
    #[serde(default)]
    pub language: String,
}

fn default_refresh_interval() -> u64 {
    30
}
fn default_metric() -> bool {
    true
}
fn default_precision() -> String {
    "exact".to_string()
}

fn default_visibility() -> String {
    "friends_only".to_string()
}

impl Default for Settings {
    fn default() -> Self {
        Self {
            refresh_interval_secs: default_refresh_interval(),
            metric: default_metric(),
            default_precision: default_precision(),
            profile_visibility: default_visibility(),
            language: String::new(),
        }
    }
}

/// Great-circle distance in metres (haversine).
pub fn haversine_m(lat1: f64, lon1: f64, lat2: f64, lon2: f64) -> f64 {
    const R: f64 = 6_371_000.0;
    let d_lat = (lat2 - lat1).to_radians();
    let d_lon = (lon2 - lon1).to_radians();
    let a = (d_lat / 2.0).sin().powi(2)
        + lat1.to_radians().cos() * lat2.to_radians().cos() * (d_lon / 2.0).sin().powi(2);
    2.0 * R * a.sqrt().asin()
}

/// Initial bearing in degrees (0=N, 90=E).
pub fn bearing_deg(lat1: f64, lon1: f64, lat2: f64, lon2: f64) -> f64 {
    let y = (lon2 - lon1).to_radians().sin() * lat2.to_radians().cos();
    let x = lat1.to_radians().cos() * lat2.to_radians().sin()
        - lat1.to_radians().sin() * lat2.to_radians().cos() * (lon2 - lon1).to_radians().cos();
    (y.atan2(x).to_degrees() + 360.0) % 360.0
}

/// Human-readable distance for the given unit preference.
pub fn format_distance(metres: f64, metric: bool) -> String {
    if metric {
        if metres < 1000.0 {
            format!("{metres:.0} m")
        } else if metres < 10_000.0 {
            format!("{:.2} km", metres / 1000.0)
        } else {
            format!("{:.1} km", metres / 1000.0)
        }
    } else {
        let miles = metres / 1609.344;
        if miles < 0.1 {
            format!("{:.0} ft", metres * 3.28084)
        } else {
            format!("{miles:.2} mi")
        }
    }
}

/// Compass label for a bearing (N, NE, E, …).
pub fn compass_label(bearing: f64) -> &'static str {
    match ((bearing + 22.5) / 45.0) as i32 % 8 {
        0 => "N",
        1 => "NE",
        2 => "E",
        3 => "SE",
        4 => "S",
        5 => "SW",
        6 => "W",
        _ => "NW",
    }
}

/// Freshness classification for a location timestamp (`live|fresh|stale|dead|unknown`).
/// Thresholds: live <60s, fresh <15min, stale <1h, else dead. Unparsable → unknown (never "live").
pub fn freshness_state(updated_at: &str, now_unix: i64) -> &'static str {
    let Some(age) = age_secs(updated_at, now_unix) else {
        return "unknown";
    };
    match age {
        0..=59 => "live",
        60..=899 => "fresh",
        900..=3599 => "stale",
        _ => "dead",
    }
}

/// Age in seconds of an ISO-8601 timestamp vs `now_unix`; None if unparsable/future.
pub fn age_secs(updated_at: &str, now_unix: i64) -> Option<u64> {
    let ts = chrono::DateTime::parse_from_rfc3339(updated_at).ok()?;
    let secs = ts.timestamp();
    if secs > now_unix {
        None
    } else {
        Some((now_unix - secs) as u64)
    }
}

#[derive(Debug, Clone, Default, PartialEq)]
pub enum AppState {
    #[default]
    Auth,
    Main,
    Admin,
}

#[derive(Debug, Clone, Default)]
pub struct AppData {
    pub user: Option<User>,
    pub friendships: Vec<Friendship>,
    pub shares: Vec<LocationShare>,
    pub locations: Vec<FriendLocation>,
    pub state: AppState,
    pub must_change_password: bool,
    pub search_results: Vec<SearchPlace>,
    pub search_error: Option<String>,
    /// Place selected from search, reverse geocode or a map tap.
    pub selected_place: Option<SearchPlace>,
    /// One-shot map tap coordinate consumed by the UI.
    pub map_click: Option<(f64, f64)>,
    /// Nearby POI results from the last Overpass query (Places screen).
    pub poi_results: Vec<crate::osm::Poi>,
    /// Last calculated route (summary/steps/GPX export).
    pub last_route: Option<crate::osm::Route>,
    /// Latest backend route alternatives and their request generation.
    pub route_results: Vec<Route>,
    pub route_error: Option<String>,
    pub route_result_seq: u64,
    /// Active server-side sessions shown in the account screen.
    pub sessions: Vec<SessionInfo>,
    /// One-time anonymous recovery code; cleared after the user dismisses it.
    pub recovery_code: Option<String>,
    /// Map appearance overrides (web appearance.js parity).
    pub map_label_size: Option<f32>,
    pub map_icon_size: Option<f32>,
    /// Latest GitHub release check result (user-initiated).
    pub update_status: UpdateStatus,
    /// Admin console payloads (web `admin/*.js` parity).
    pub admin_overview: Option<serde_json::Value>,
    pub admin_users: Vec<serde_json::Value>,
    pub admin_audit: Vec<AdminAuditEntry>,
    pub admin_reports: Vec<DiagnosticReport>,
    pub admin_report_total: i64,
    pub admin_report_open: i64,
    // New feature state (populated by the server where applicable).
    pub my_location: Option<FriendLocation>,
    pub check_ins: Vec<CheckIn>,
    pub emergencies: Vec<EmergencyAlert>,
    pub users: Vec<User>,
    pub settings: Settings,
    pub bookmarks_count: usize,
    /// Pending MFA enrolment secret (set by enroll, cleared on verify).
    pub totp_pending_secret: Option<String>,
    /// Whether the signed-in user's account has MFA enabled (from login/status).
    pub mfa_enabled: bool,
    /// Interactive map zoom level (2..=18; 0 means uninitialized → defaults to 13).
    pub map_zoom: u8,
    /// Interactive map center latitude (defaults to Chișinău 47.0105 when 0.0).
    pub map_center_lat: f64,
    /// Interactive map center longitude (defaults to Chișinău 28.8638 when 0.0).
    pub map_center_lon: f64,
    /// Accumulated pinch zoom (natural log of the gesture factor) so a
    /// multi-finger pinch steps through zoom levels proportionally.
    pub map_pinch_accum: f32,
    /// Most recent E2E-encrypted location payload produced on this device.
    pub last_e2e_location_ciphertext: Option<String>,
    /// Resolved kiosk/share-link view model (Kiosk screen).
    pub kiosk_resolved: Option<crate::webapp::kiosk::KioskShareView>,
    /// Map raster style: false = clean light OSM (Organic/Magic-Earth-like),
    /// true = the web client's dark treatment.
    pub map_dark: bool,
}

#[cfg(test)]
mod geo_tests {
    use super::{bearing_deg, compass_label, format_distance, haversine_m, LocationShare};

    #[test]
    fn haversine_known_distance() {
        // Chicago landmarks: ~1.6 km apart. Zero distance is exact.
        assert_eq!(haversine_m(41.8902, -87.6323, 41.8902, -87.6323), 0.0);
        let d = haversine_m(41.8902, -87.6323, 41.8781, -87.6298);
        assert!(d > 1300.0 && d < 1700.0, "distance was {d}");
    }

    #[test]
    fn bearing_and_compass() {
        // Due north.
        let b = bearing_deg(41.0, -87.0, 42.0, -87.0);
        assert!(b < 1.0 || b > 359.0, "bearing was {b}");
        assert_eq!(compass_label(b), "N");
        assert_eq!(compass_label(90.0), "E");
        assert_eq!(compass_label(180.0), "S");
        assert_eq!(compass_label(270.0), "W");
    }

    #[test]
    fn distance_formatting() {
        assert_eq!(format_distance(500.0, true), "500 m");
        assert_eq!(format_distance(1609.0, true), "1.61 km");
        assert_eq!(format_distance(1609.0, false), "1.00 mi");
    }

    #[test]
    fn share_expiry_deserializes_with_defaults() {
        let v = serde_json::json!({
            "id": 1, "friendship_id": 2, "owner_id": 3,
            "direction": "mutual", "precision_level": "exact", "is_active": true
        });
        let s: LocationShare = serde_json::from_value(v).expect("legacy share JSON");
        assert!(s.expires_at.is_none());
        assert!(s.label.is_none());
    }

    #[test]
    fn freshness_thresholds() {
        use super::{age_secs, freshness_state};
        let now = 1_784_000_000i64; // fixed reference point
        let iso = chrono::DateTime::from_timestamp(now - 10, 0)
            .unwrap()
            .to_rfc3339();
        assert_eq!(age_secs(&iso, now), Some(10));
        assert_eq!(freshness_state(&iso, now), "live");
        let stale = chrono::DateTime::from_timestamp(now - 2000, 0)
            .unwrap()
            .to_rfc3339();
        assert_eq!(freshness_state(&stale, now), "stale");
        let dead = chrono::DateTime::from_timestamp(now - 7200, 0)
            .unwrap()
            .to_rfc3339();
        assert_eq!(freshness_state(&dead, now), "dead");
        assert_eq!(freshness_state("not-a-date", now), "unknown");
    }
}
